mapper.select:
SELECT i.* FROM interviews i
INNER JOIN jobs j ON i.job_id = j.id AND j.is_delete = 0
WHERE i.is_delete = 0
AND j.hr_id = #{hrId}
ORDER BY i.start_time DESC LIMIT #{offset}, #{pageSize}

SELECT *
FROM interviews
WHERE is_delete = 0
  AND start_time  >=  #{startDate}
  AND start_time  <=  #{endDate}
ORDER BY start_time ASC
